import { useState, useEffect } from "react";
import api from "../api";
import { useToast } from "../context/ToastContext";
import Skeleton from "../components/Skeleton";
import "../components/skeleton.css";

export default function AdminDashboard() {

  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [users, setUsers] = useState([]);
  const [providers, setProviders] = useState([]);

  const [paymentConfig, setPaymentConfig] = useState({
    upiIds: [],
    qrCodes: [],
    bankAccounts: [],
    cardSupported: true,
    codSupported: true,
    enabled: true
  });

  const [qrFile, setQrFile] = useState(null);

  const [newService, setNewService] = useState({
    name: "",
    category: "",
    rating: 0
  });

  const [activeTab, setActiveTab] =
    useState("services");

  const [loading, setLoading] =
    useState(true);

  const { addToast } = useToast();

  // =====================================================
  // LOAD DATA
  // =====================================================

  useEffect(() => {

    loadData();

  }, []);

  const loadData = async () => {

    try {

      setLoading(true);

      const [

        servicesRes,
        bookingsRes,
        usersRes,
        providersRes,
        paymentRes

      ] = await Promise.all([

        api.get("/services"),

        api.get("/bookings"),

        api.get("/auth/users"),

        api.get("/auth/providers"),

        api.get("/admin-payments/config")

      ]);

      setServices(
        servicesRes.data || []
      );

      setBookings(
        bookingsRes.data || []
      );

      setUsers(
        usersRes.data || []
      );

      setProviders(
        providersRes.data || []
      );

      setPaymentConfig({

        upiIds:
          paymentRes.data?.upiIds || [],

        qrCodes:
          paymentRes.data?.qrCodes || [],

        bankAccounts:
          paymentRes.data?.bankAccounts || [],

        cardSupported:
          paymentRes.data?.cardSupported ?? true,

        codSupported:
          paymentRes.data?.codSupported ?? true,

        enabled:
          paymentRes.data?.enabled ?? true

      });

    } catch (err) {

      console.log(err);

      addToast(
        "Failed to load admin data",
        "error"
      );

    } finally {

      setLoading(false);

    }

  };

  // =====================================================
  // SAVE PAYMENT CONFIG
  // =====================================================

  const handlePaymentConfigSave =
    async () => {

      try {

        const payload = {

          upiIds:
            paymentConfig.upiIds || [],

          bankAccounts:
            paymentConfig.bankAccounts || [],

          cardSupported:
            paymentConfig.cardSupported,

          codSupported:
            paymentConfig.codSupported,

          enabled:
            paymentConfig.enabled

        };

        const res =
          await api.put(

            "/admin-payments/config",

            payload

          );

        setPaymentConfig(
          res.data.config
        );

        addToast(
          "Payment configuration saved",
          "success"
        );

      } catch (err) {

        console.log(err);

        addToast(
          "Failed to save payment configuration",
          "error"
        );

      }

    };

  // =====================================================
  // QR UPLOAD
  // =====================================================

  const handleUploadQr =
    async () => {

      try {

        if (!qrFile) {

          return addToast(
            "Select QR image first",
            "error"
          );

        }

        const formData =
          new FormData();

        formData.append(
          "qrCode",
          qrFile
        );

        formData.append(
          "label",
          qrFile.name
        );

        const res =
          await api.post(

            "/admin-payments/upload-qr",

            formData,

            {

              headers: {

                "Content-Type":
                  "multipart/form-data"

              }

            }

          );

        setPaymentConfig(
          res.data.config
        );

        setQrFile(null);

        addToast(
          "QR uploaded successfully",
          "success"
        );

      } catch (err) {

        console.log(err);

        addToast(
          "QR upload failed",
          "error"
        );

      }

    };

  // =====================================================
  // DELETE QR
  // =====================================================

  const handleDeleteQr =
    async (id) => {

      try {

        const res =
          await api.delete(

            `/admin-payments/qr/${id}`

          );

        setPaymentConfig(
          res.data.config
        );

        addToast(
          "QR deleted",
          "success"
        );

      } catch (err) {

        console.log(err);

        addToast(
          "Failed to delete QR",
          "error"
        );

      }

    };

  // =====================================================
  // REMOVE UPI
  // =====================================================

  const removeUpi =
    (index) => {

      const next =
        [...paymentConfig.upiIds];

      next.splice(index, 1);

      setPaymentConfig({

        ...paymentConfig,

        upiIds: next

      });

    };

  // =====================================================
  // REMOVE BANK
  // =====================================================

  const removeBank =
    (index) => {

      const next =
        [...paymentConfig.bankAccounts];

      next.splice(index, 1);

      setPaymentConfig({

        ...paymentConfig,

        bankAccounts: next

      });

    };

  // =====================================================
  // UI
  // =====================================================

  return (

    <div className="dashboard-container">

      <header className="dashboard-header">

        <div className="dashboard-logo">

          🚀 FastAid

        </div>

        <button

          className="logout-btn"

          onClick={() => {

            localStorage.removeItem(
              "token"
            );

            window.location.href = "/";

          }}

        >

          Logout

        </button>

      </header>

      <div className="dashboard-content">

        <h1 className="dashboard-title">

          Admin Dashboard ⚙️

        </h1>

        <p className="dashboard-subtitle">

          Manage platform & payment settings

        </p>

        {/* ================================= */}
        {/* TABS */}
        {/* ================================= */}

        <div className="tabs">

          <button
            className={`tab ${
              activeTab === "payments"
                ? "active"
                : ""
            }`}
            onClick={() =>
              setActiveTab("payments")
            }
          >
            💳 Payments
          </button>

        </div>

        {/* ================================= */}
        {/* PAYMENTS TAB */}
        {/* ================================= */}

        {activeTab === "payments" && (

          <div className="dashboard-form">

            {loading ? (

              <Skeleton
                count={4}
                height="50px"
              />

            ) : (

              <>

                {/* ===================== */}
                {/* UPI */}
                {/* ===================== */}

                <div>

                  <h3>
                    UPI IDs
                  </h3>

                  {paymentConfig.upiIds.map(
                    (upi, index) => (

                      <div
                        key={index}
                        style={{
                          display: "flex",
                          gap: "10px",
                          marginBottom: "10px"
                        }}
                      >

                        <input

                          type="text"

                          value={upi.value}

                          placeholder="UPI ID"

                          className="form-input"

                          onChange={(e) => {

                            const next =
                              [...paymentConfig.upiIds];

                            next[index] = {

                              ...next[index],

                              value:
                                e.target.value

                            };

                            setPaymentConfig({

                              ...paymentConfig,

                              upiIds: next

                            });

                          }}

                        />

                        <button

                          className="btn btn-danger"

                          onClick={() =>
                            removeUpi(index)
                          }

                        >

                          Delete

                        </button>

                      </div>

                    )
                  )}

                  <button

                    className="btn btn-secondary"

                    onClick={() =>

                      setPaymentConfig({

                        ...paymentConfig,

                        upiIds: [

                          ...paymentConfig.upiIds,

                          {
                            value: "",
                            label: "UPI"
                          }

                        ]

                      })

                    }

                  >

                    Add UPI

                  </button>

                </div>

                {/* ===================== */}
                {/* BANKS */}
                {/* ===================== */}

                <div
                  style={{
                    marginTop: "30px"
                  }}
                >

                  <h3>
                    Bank Accounts
                  </h3>

                  {paymentConfig.bankAccounts.map(
                    (bank, index) => (

                      <div
                        key={index}
                        style={{
                          marginBottom: "20px"
                        }}
                      >

                        <input
                          className="form-input"
                          placeholder="Bank Name"
                          value={bank.bankName}
                          onChange={(e) => {

                            const next =
                              [...paymentConfig.bankAccounts];

                            next[index] = {

                              ...next[index],

                              bankName:
                                e.target.value

                            };

                            setPaymentConfig({

                              ...paymentConfig,

                              bankAccounts:
                                next

                            });

                          }}
                        />

                        <input
                          className="form-input"
                          placeholder="Account Number"
                          value={bank.accountNumber}
                          onChange={(e) => {

                            const next =
                              [...paymentConfig.bankAccounts];

                            next[index] = {

                              ...next[index],

                              accountNumber:
                                e.target.value

                            };

                            setPaymentConfig({

                              ...paymentConfig,

                              bankAccounts:
                                next

                            });

                          }}
                        />

                        <button

                          className="btn btn-danger"

                          onClick={() =>
                            removeBank(index)
                          }

                        >

                          Delete

                        </button>

                      </div>

                    )
                  )}

                  <button

                    className="btn btn-secondary"

                    onClick={() =>

                      setPaymentConfig({

                        ...paymentConfig,

                        bankAccounts: [

                          ...paymentConfig.bankAccounts,

                          {

                            bankName: "",
                            accountNumber: "",
                            accountName: "",
                            ifsc: ""

                          }

                        ]

                      })

                    }

                  >

                    Add Bank

                  </button>

                </div>

                {/* ===================== */}
                {/* QR */}
                {/* ===================== */}

                <div
                  style={{
                    marginTop: "30px"
                  }}
                >

                  <h3>
                    QR Upload
                  </h3>

                  <input

                    type="file"

                    accept="image/*"

                    onChange={(e) =>

                      setQrFile(
                        e.target.files?.[0]
                      )

                    }

                  />

                  <button

                    className="btn btn-primary"

                    onClick={handleUploadQr}

                  >

                    Upload QR

                  </button>

                  <div
                    style={{
                      marginTop: "20px"
                    }}
                  >

                    {paymentConfig.qrCodes.map(
                      (qr) => (

                        <div
                          key={qr._id}
                          style={{
                            marginBottom: "20px"
                          }}
                        >

                          <img

                            src={`http://localhost:5000${qr.url}`}

                            alt="QR"

                            width="150"

                            style={{
                              borderRadius: "10px"
                            }}

                          />

                          <div>

                            <button

                              className="btn btn-danger"

                              onClick={() =>
                                handleDeleteQr(
                                  qr._id
                                )
                              }

                            >

                              Delete

                            </button>

                          </div>

                        </div>

                      )
                    )}

                  </div>

                </div>

                {/* ===================== */}
                {/* SAVE */}
                {/* ===================== */}

                <button

                  className="btn btn-primary"

                  style={{
                    marginTop: "30px"
                  }}

                  onClick={
                    handlePaymentConfigSave
                  }

                >

                  Save Payment Configuration

                </button>

              </>

            )}

          </div>

        )}

      </div>

    </div>

  );

}
